static const int32_t MLP_B1[32] = {40, 40, 39, 39, 41, 39, 39, 40, 40, 39, 40, 41, 40, 40, 39, 40, 39, 39, 40, 39, 39, 39, 40, 39, 40, 40, 40, 41, 39, 39, 41, 40};
